<script setup lang="ts">
import { defineAsyncComponent, onMounted, onBeforeUnmount, ref, watch, nextTick } from 'vue';
import { ShieldCheck, Bell, CircleHelp, ArrowUpRight, Plus, Search, Menu, ChevronRight, ChevronLeft, Download, RefreshCw, MapPin, ArrowRight, TriangleAlert, CheckCircle2, LogOut, X, SlidersHorizontal, WifiOff, Leaf, Building2 as BuildingIcon, ClipboardList, House, Map as MapIcon, Settings } from '@lucide/vue';
import { labels, relativeTime } from '../types';
import identity from '../config/identity.json';
const UserGuide = defineAsyncComponent(() => import('../components/UserGuide.vue'));
const FeatureTour = defineAsyncComponent(() => import('../components/FeatureTour.vue'));
const touring = ref(false);
async function startTour() { navigate('overview'); await nextTick(); touring.value = true; }
import { useDashboard } from '../composables/useDashboard';
import Modal from '../components/Modal.vue';
import AuthForm from '../components/AuthForm.vue';
import ReportForm from '../components/ReportForm.vue';
import ReportDetail from '../components/ReportDetail.vue';
import ReportCards from '../components/ReportCards.vue';
import HazardIcon from '../components/HazardIcon.vue';
import MapControls from '../components/MapControls.vue';
const mapView = ref<{ zoomTo: (level: number) => void; fitReports: () => void; fitServiceArea: () => void }>();
const mapZoom = ref(12.5);
import AdminCms from '../components/AdminCms.vue';
const IncidentAnalytics = defineAsyncComponent(() => import('../components/IncidentAnalytics.vue'));
import ProfilePanel from '../components/ProfilePanel.vue';
import NewsFeed from '../components/NewsFeed.vue';
import ConfirmDialog from '../components/ConfirmDialog.vue';
const confirmLogout = ref(false); const confirmCancel = ref(false); const philippineTime = ref(''); let clockTimer: ReturnType<typeof setInterval>;
function updateClock() { philippineTime.value = new Intl.DateTimeFormat('en-PH', { timeZone: 'Asia/Manila', weekday: 'short', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit' }).format(new Date()) + ' PHT'; }
onMounted(() => { updateClock(); clockTimer = setInterval(updateClock, 1000); }); onBeforeUnmount(() => clearInterval(clockTimer));
const HazardMap = defineAsyncComponent(() => import('../components/HazardMap.vue'));
const { view,mobileNav,demo,user,reports,categories,departments,stats,notices,loading,online,error,search,category,status,page,lastPage,total,modal,selected,toast,pendingReport,socialIntent,synced,pushBusy,municipality,navigation,heading,filtered,urgent,unread,metricCards,municipalSettings,notify,refresh,navigate,startReport,cancelAuth,signedIn,logout,created,toggleDemo,push,markRead,openNotice,exportCsv } = useDashboard();
const compactQuery = window.matchMedia('(max-width: 1023px)');
const compact = ref(compactQuery.matches);
let drawerOverflow = '';
function updateCompact() { compact.value = compactQuery.matches; if (!compact.value) mobileNav.value = false; }
onMounted(() => compactQuery.addEventListener('change', updateCompact));
onBeforeUnmount(() => { compactQuery.removeEventListener('change', updateCompact); if (mobileNav.value) document.body.style.overflow = drawerOverflow; });
watch(mobileNav, async open => {
  if (open) { drawerOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden'; }
  else document.body.style.overflow = drawerOverflow;
  await nextTick();
  if (open) document.querySelector<HTMLButtonElement>('.sidebar nav button')?.focus();
  else if (compact.value && !modal.value && !selected.value) document.querySelector<HTMLButtonElement>('.nav-more')?.focus();
});
watch(modal, value => { if (value) mobileNav.value = false; });
</script>
<template>
  <div class="app-layout" @keydown.esc="mobileNav = false">
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <button v-if="mobileNav" class="sidebar-backdrop" aria-label="Close navigation" @click="mobileNav = false"></button>
    <aside id="workspace-navigation" aria-label="Workspace navigation" :inert="compact && !mobileNav" class="sidebar" :class="{ open: mobileNav }"><a class="brand" href="/" @click.prevent="navigate('overview')"><div class="brand-icon"><ShieldCheck :size="29" /></div><div><strong>{{ identity.name }}<span>.</span></strong><small>{{ identity.subtitle }}</small></div></a><div class="workspace"><div class="workspace-symbol"><BuildingIcon /></div><div><strong>{{ municipality }}</strong><small>{{ user?.role === 'admin' ? 'Municipal operations workspace' : 'Community safety workspace' }}</small></div></div><span class="nav-caption">WORKSPACE</span><nav><button v-for="item in navigation" :key="item.id" :aria-current="view === item.id ? 'page' : undefined" :class="{ active: view === item.id }" @click="navigate(item.id)"><component :is="item.icon" :size="20" /><span>{{ item.label }}</span><span v-if="item.id === 'reports' && stats.active" class="nav-count">{{ stats.active }}</span><span v-if="item.id === 'activity' && unread" class="nav-count">{{ unread }}</span></button></nav><div class="sidebar-bottom"><div v-if="user?.role !== 'admin'" class="community-card"><div class="community-illustration"><ShieldCheck :size="43" /><Leaf :size="23" /></div><strong>A safer community<br>starts with you.</strong><p>Spot a hazard. Share a report.<br>Make a difference.</p><button @click="startReport">Let’s keep our town safe <ArrowUpRight :size="15" /></button></div><button class="help-link" @click="navigate('guide')"><CircleHelp :size="19" />Guide & user manual<ArrowUpRight :size="15" /></button><div class="sidebar-user"><div class="avatar">{{ user ? user.name.charAt(0).toUpperCase() : 'G' }}</div><div><strong>{{ user?.name || 'Community guest' }}</strong><small>{{ user?.role === 'admin' ? 'Municipal administrator' : user ? 'Citizen account' : 'Everyone can make a difference' }}</small></div><button v-if="user" class="icon-button" aria-label="Sign out" @click="confirmLogout = true"><LogOut :size="18" /></button><button v-else class="text-button" @click="modal = 'auth'">Sign in</button></div></div></aside>
    <div class="main-shell" :inert="compact && mobileNav"><header class="topbar"><div class="breadcrumb"><span>{{ identity.name }}</span><ChevronRight :size="14" /><strong>{{ navigation.find(n => n.id === view)?.label }}</strong></div><div class="top-actions"><button class="icon-button" aria-label="Open guide and user manual" @click="navigate('guide')"><CircleHelp :size="21" /></button><time class="ph-clock" aria-label="Philippine time">{{ philippineTime }}</time><span class="connection" :class="{ demo, disconnected: !online && !demo }" :aria-label="demo ? 'Demo workspace' : online ? 'Connected to municipality' : 'Connecting to municipality'" :title="demo ? 'Demo workspace' : online ? 'Connected' : 'Connecting to municipality'"><i></i>{{ demo ? 'Demo workspace' : online ? 'Connected' : 'Connecting to municipality' }}</span><button v-if="user?.role !== 'admin'" class="icon-button notification-button" aria-label="Open notifications" @click="navigate('activity')"><Bell :size="20" /><i v-if="unread"></i></button><button class="avatar top-avatar" aria-label="Account" @click="user ? navigate('profile') : modal = 'auth'">{{ user?.name.charAt(0).toUpperCase() || 'G' }}</button></div></header>
    <main id="main-content" tabindex="-1">
      <div v-if="demo" class="demo-banner"><span><strong>Demo workspace</strong> · Fictional reports for exploring the interface. No reports are sent.</span><button @click="toggleDemo(false)">Exit preview <X :size="14" /></button></div>
      <section class="page-heading"><div><div class="eyebrow workspace-eyebrow">{{ user?.role === 'admin' ? 'Municipal operations' : 'Community safety' }}</div><h1>{{ heading }}</h1><p>{{ view === 'overview' ? 'Stay informed. Report hazards. Help keep your community safe.' : view === 'mine' ? 'Follow your reports from submission to resolution.' : view === 'activity' ? 'The latest updates on your reports and municipal response.' : 'A clearer view of what’s happening around you.' }}</p><time class="mobile-clock" aria-label="Philippine time">{{ philippineTime }}</time></div><button v-if="user?.role !== 'admin'" class="button primary report-button" @click="startReport"><Plus :size="19" />Report a hazard</button></section>
      <div v-if="error" class="server-error" role="alert"><WifiOff :size="23" /><div><strong>Municipal server unavailable</strong><p>{{ error }}</p></div><button class="button secondary" @click="refresh()">Retry</button><button class="text-button" @click="toggleDemo(true)">Explore demo</button></div>
      <template v-if="view === 'overview'"><section class="metrics"><article v-for="card in metricCards" :key="card.label" class="metric-card"><div class="metric-top"><span>{{ card.label }}</span><div class="metric-icon" :class="card.color"><component :is="card.icon" :size="19" /></div></div><div class="metric-value">{{ loading ? '—' : card.value.toString().padStart(2, '0') }}<span v-if="card.color === 'green'" class="tiny-check"><CheckCircle2 :size="14" />Community impact</span></div><small>{{ card.detail }}</small></article></section></template>
      <template v-if="['overview', 'map', 'reports', 'mine'].includes(view)">
        <section class="filter-bar" aria-label="Report filters"><div class="search-field"><Search :size="18" /><input v-model="search" aria-label="Search reports" placeholder="Search reports, locations, or reference number…"><button v-if="search" class="icon-button" aria-label="Clear search" @click="search = ''"><X :size="15" /></button></div><div class="filter-selects"><SlidersHorizontal :size="16" /><select v-model="category" aria-label="Filter by category"><option value="">All categories</option><option v-for="item in categories" :key="item.id" :value="item.id">{{ item.name }}</option></select><select v-model="status" aria-label="Filter by status"><option value="">All statuses</option><option v-for="(label, value) in labels" :key="value" :value="value">{{ label }}</option></select><button class="icon-button refresh-button" aria-label="Refresh reports" :disabled="loading" @click="refresh()"><RefreshCw :size="17" :class="{ spin: loading }" /></button></div></section>
        <div v-if="search || category || status" class="filter-summary"><span role="status">{{ loading ? 'Finding reports?' : `${total} matching reports` }}</span><button class="text-button" @click="search = ''; category = ''; status = ''">Clear filters</button></div>
        <section v-if="view === 'overview' || view === 'map'" class="map-section" :class="{ expanded: view === 'map' }"><div class="map-panel"><div class="panel-heading"><div><h2>Hazard map <span class="pill">{{ filtered.length }} on this page</span></h2><p>A view of reported hazards in your community</p></div><button class="text-button" @click="navigate(view === 'map' ? 'overview' : 'map')">{{ view === 'map' ? 'Overview' : 'Expand map' }}<ArrowUpRight :size="15" /></button></div><MapControls :categories="categories" :category="category" :visible="filtered.length" :total="total" :loading="loading" :zoom="mapZoom" @category="category = $event" @fit="mapView?.fitReports()" @area="mapView?.fitServiceArea()" @zoom="mapView?.zoomTo($event)" /><div class="dashboard-map"><HazardMap ref="mapView" :reports="filtered" @select="selected = $event" @zoom="mapZoom = $event" /></div><div class="map-footer"><div class="map-note" role="status"><span class="map-note-dot"></span>{{ demo ? 'Demonstration locations' : user?.role === 'admin' ? 'Private incident locations' : 'Approximate public areas' }}</div><div class="map-legend"><span><i class="critical"></i>Critical</span><span><i class="high"></i>High</span><span><i class="moderate"></i>Moderate / low</span><span><i class="resolved"></i>Resolved</span></div><p class="map-service-area">Basista, Pangasinan · 13 barangays</p></div><div v-if="view === 'map' && lastPage > 1" class="map-pagination"><span>Map page {{ page }} / {{ lastPage }}</span><button type="button" class="button secondary" :disabled="page <= 1 || loading" @click="page--; refresh()">Previous map page</button><button type="button" class="button secondary" :disabled="page >= lastPage || loading" @click="page++; refresh()">Next map page</button></div></div><aside v-if="view === 'overview'" class="attention-panel"><div class="panel-heading"><div><h2>Needs attention</h2><p>Recent active reports</p></div><span class="orange-dot"></span></div><div v-if="!urgent.length" class="small-empty"><ShieldCheck :size="29" /><strong>{{ loading ? 'Loading reports…' : 'No active reports to show' }}</strong><p>New reports will appear here.</p></div><button v-for="report in urgent" :key="report.id" class="attention-report" @click="selected = report"><div class="attention-top"><span class="category-icon" :class="report.category.id"><HazardIcon :category="report.category.id" :size="19" /></span><span class="severity" :class="report.severity">{{ report.severity }}</span></div><h3>{{ report.title }}</h3><p><MapPin :size="13" />{{ report.barangay }}</p><div class="attention-foot"><span class="status" :class="report.status">{{ labels[report.status] }}</span><small>{{ relativeTime(report.created_at) }}</small></div></button><button class="view-all" @click="navigate('reports')">View all reports<ArrowRight :size="16" /></button></aside></section>
        <section v-if="view !== 'map'" class="reports-panel" :aria-busy="loading"><div class="panel-heading"><div><h2>{{ view === 'mine' ? 'Your submitted reports' : 'Recent reports' }} <span class="pill">{{ total }}</span></h2><p>{{ view === 'mine' ? 'Select a report to see its status history' : 'Every report is a step toward a safer community' }}</p></div><button class="button secondary small" :disabled="!filtered.length" @click="exportCsv"><Download :size="15" />Export page</button></div><div v-if="!filtered.length" class="empty-state"><ClipboardList :size="34" /><h3>{{ loading ? 'Loading reports…' : 'No reports found' }}</h3><p>{{ search || category || status ? 'Try another search or clear your filters.' : 'Reports will appear here when submitted to your municipality.' }}</p><button v-if="!loading && !online && !demo" class="button secondary" @click="toggleDemo(true)">Explore the demo workspace</button></div><template v-else><ReportCards :reports="filtered.slice(0, view === 'overview' ? 5 : 100)" @select="selected = $event" /><div class="table-scroll"><table><thead><tr><th>HAZARD DETAILS</th><th>LOCATION</th><th>PRIORITY</th><th>STATUS</th><th>REPORTED</th><th><span class="visually-hidden">Open report</span></th></tr></thead><tbody><tr v-for="report in filtered.slice(0, view === 'overview' ? 5 : 100)" :key="report.id"><td><button class="table-report" @click="selected = report"><span class="category-icon" :class="report.category.id"><HazardIcon :category="report.category.id" /></span><span><strong>{{ report.title }}</strong><small>{{ report.reference_number }} <span>·</span> {{ report.category.name }}</small></span></button></td><td><div class="table-location"><MapPin :size="14" />{{ report.barangay }}</div></td><td><span class="severity" :class="report.severity">{{ report.severity }}</span></td><td><span class="status" :class="report.status">{{ labels[report.status] }}</span></td><td class="muted nowrap">{{ relativeTime(report.created_at) }}</td><td><button class="icon-button" :aria-label="`Open ${report.reference_number}`" @click="selected = report"><ChevronRight :size="17" /></button></td></tr></tbody></table></div></template><footer class="table-footer"><span>Showing {{ Math.min(filtered.length, view === 'overview' ? 5 : 100) }} reports{{ demo ? ' · Demo data' : '' }}</span><button v-if="view === 'overview'" class="text-button" @click="navigate('reports')">View all reports <ArrowRight :size="15" /></button><div v-else class="pagination"><button class="icon-button" :disabled="page <= 1" aria-label="Previous page" @click="page--; refresh()"><ChevronLeft :size="17" /></button><span>{{ page }} / {{ lastPage }}</span><button class="icon-button" :disabled="page >= lastPage" aria-label="Next page" @click="page++; refresh()"><ChevronRight :size="17" /></button></div></footer></section>
      </template>
      <section v-if="view === 'activity'" class="notifications-panel"><div class="panel-heading"><div><h2>Report updates <span class="pill">{{ unread }} unread</span></h2><p>Status changes and notes from your municipality</p></div><div class="button-row"><button class="button secondary small" :disabled="pushBusy || !user || demo" @click="push"><Bell :size="15" />{{ pushBusy ? 'Enabling…' : 'Enable push' }}</button><button class="text-button" :disabled="!unread" @click="markRead">Mark all read</button></div></div><div v-if="!notices.length" class="empty-state"><Bell :size="35" /><h3>You’re all caught up</h3><p>Updates on your submitted reports will appear here.</p></div><button v-for="notice in notices" :key="notice.id" class="notification-row" :class="{ unread: !notice.read_at }" @click="openNotice(notice)"><div class="metric-icon green"><CheckCircle2 :size="20" /></div><div><strong>{{ notice.data.reference_number }}</strong><p>{{ notice.data.message }}</p><small>{{ relativeTime(notice.created_at) }}</small></div><ChevronRight :size="18" /></button></section>
      <section v-if="view === 'guide'"><UserGuide :user="user" @tour="startTour" @report="startReport" @review="navigate('reports')" /></section>
      <section v-if="view === 'analytics' && user?.role === 'admin'"><IncidentAnalytics :categories="categories" /></section>
      <section v-if="view === 'cms' && user?.role === 'admin'"><AdminCms /></section>
      <section v-if="view === 'profile' && user"><ProfilePanel :user="user" @updated="user = $event" /></section>
      <section v-if="view === 'news'"><NewsFeed :user="user" :demo="demo" @sign-in="modal = 'auth'" /></section>
      <section v-if="view === 'overview' && user?.role !== 'admin' && municipalSettings.hotlines.length" class="hotlines-card"><h2>Emergency hotlines</h2><p>Call directly if someone is in immediate danger.</p><div><a v-for="line in municipalSettings.hotlines" :key="line.name" :href="`tel:${line.number}`">{{ line.name }} ? {{ line.number }}</a></div></section>
      <footer class="page-footer"><span><ShieldCheck :size="14" />Built for a safer, more connected community.</span><span>{{ demo ? 'Preview · No live incidents' : synced ? `Last synced ${synced}` : identity.name + ' - ' + identity.subtitle }}</span></footer>
    </main></div>
    <nav v-liquid-glass class="mobile-dock" aria-label="Quick navigation" :inert="mobileNav || !!modal || !!selected || confirmLogout || confirmCancel || touring">
      <button :aria-current="view === 'overview' ? 'page' : undefined" @click="navigate('overview')"><House :size="21" /><span>Home</span></button>
      <button :aria-current="view === 'map' ? 'page' : undefined" @click="navigate('map')"><MapIcon :size="21" /><span>Map</span></button>
      <button v-if="user?.role !== 'admin'" class="dock-report" aria-label="Create hazard report" @click="startReport"><Plus :size="23" /><span>Report</span></button>
      <button v-else :aria-current="view === 'reports' ? 'page' : undefined" @click="navigate('reports')"><ClipboardList :size="21" /><span>Review</span></button>
      <button v-if="user?.role !== 'admin'" :aria-current="view === 'activity' ? 'page' : undefined" @click="navigate('activity')"><span class="dock-icon"><Bell :size="21" /><i v-if="unread" class="dock-unread"></i></span><span>Updates</span></button>
      <button v-else :aria-current="view === 'cms' ? 'page' : undefined" @click="navigate('cms')"><Settings :size="21" /><span>Manage</span></button>
      <button class="nav-more" aria-label="More navigation" aria-controls="workspace-navigation" :aria-expanded="mobileNav" @click="mobileNav = true"><Menu :size="21" /><span>More</span></button>
    </nav>
    <div v-if="toast" class="toast" role="status"><CheckCircle2 :size="19" /><span>{{ toast }}</span><button aria-label="Dismiss notification" @click="toast = ''"><X :size="16" /></button></div>
    <FeatureTour v-if="touring" :admin="user?.role === 'admin'" @close="touring = false" @manual="touring = false; navigate('guide')" />
    <Modal v-if="modal === 'auth'" title="Welcome to your community" @close="cancelAuth"><AuthForm :social-intent="socialIntent" @success="signedIn" /></Modal>
    <Modal v-if="modal === 'report'" title="Report a hazard" wide @close="confirmCancel = true"><ReportForm :categories="categories" :demo="demo" @created="created" /></Modal>
    <Modal v-if="selected" title="Hazard report" wide @close="selected = null"><ReportDetail :initial="selected" :user="user" :departments="departments" :demo="demo" @updated="refresh(true)" @deleted="selected = null; notify('Unverified report deleted.'); refresh()" /></Modal>
    <ConfirmDialog v-if="confirmLogout" title="Sign out?" message="You will need to sign in again to manage reports and your profile." confirm-label="Sign out" @close="confirmLogout = false" @confirm="confirmLogout = false; logout()" />
    <ConfirmDialog v-if="confirmCancel" title="Discard this report?" message="Your unsent report and selected photos will be lost." danger confirm-label="Discard report" @close="confirmCancel = false" @confirm="confirmCancel = false; modal = null" />
  </div>
</template>
